export const imageLimits=Object.freeze({bytes:32*1024*1024,edge:16000,pixels:64000000});
export function validateImageSize(width,height){if(!Number.isInteger(width)||!Number.isInteger(height)||width<1||height<1)throw Error('图片尺寸无效');if(width>imageLimits.edge||height>imageLimits.edge||width*height>imageLimits.pixels)throw Error(`原图 ${width} × ${height} px 超过 16000 px 边长或 6400 万像素限制，请先明确缩小原图后再上传`);return {width,height};}
const positive=value=>Number.isFinite(value)&&value>0&&value<=100000;
export function normalizePrintMetadata(value,width,height){if(!value||typeof value!=='object')return undefined;const print={};for(const key of ['widthCm','heightCm','dpi'])if(positive(Number(value[key])))print[key]=Number(value[key]);if(!Object.keys(print).length)return undefined;if(print.dpi){if(!print.widthCm&&width)print.widthCm=width/print.dpi*2.54;if(!print.heightCm&&height)print.heightCm=height/print.dpi*2.54;}return print;}
export function printMetadata(source){return normalizePrintMetadata(source?.printMetadata,source?.width,source?.height);}
export function setPrintMetadata(target,value){const print=normalizePrintMetadata(value,target.width,target.height);if(print)target.printMetadata=print;else delete target.printMetadata;return target;}
export function resizedPrintMetadata(value,source,target){const print=normalizePrintMetadata(value,source.width,source.height);if(!print)return undefined;if(source.width===target.width&&source.height===target.height)return {...print};if(print.widthCm)print.dpi=target.width/print.widthCm*2.54;else if(print.dpi)print.dpi*=target.width/source.width;return normalizePrintMetadata(print,target.width,target.height);}
const pngSignature=[137,80,78,71,13,10,26,10];
export function imageHeader(input){const b=new Uint8Array(input),v=new DataView(b.buffer,b.byteOffset,b.byteLength);let width,height,print;
  if(b.length>=33&&pngSignature.every((n,i)=>b[i]===n)){width=v.getUint32(16);height=v.getUint32(20);validateImageSize(width,height);let offset=8;while(offset+12<=b.length){const length=v.getUint32(offset),end=offset+length+12;if(end>b.length)throw Error('PNG 数据不完整');const type=String.fromCharCode(...b.subarray(offset+4,offset+8));if(type==='pHYs'&&length===9&&b[offset+16]===1){const x=v.getUint32(offset+8),y=v.getUint32(offset+12);if(x&&y)print={widthCm:width/x*100,heightCm:height/y*100,dpi:x*.0254};}if(type==='tEXt'&&length<512){const text=new TextDecoder().decode(b.subarray(offset+8,offset+8+length));if(text.startsWith('zhijing-print\0'))try{print=normalizePrintMetadata(JSON.parse(text.slice(14)),width,height)||print;}catch{}}if(type==='IEND')break;offset=end;}return {width,height,printMetadata:normalizePrintMetadata(print,width,height)};}
  if(b.length>4&&b[0]===255&&b[1]===216){let offset=2;while(offset+4<=b.length){if(b[offset++]!==255)continue;while(offset<b.length&&b[offset]===255)offset++;if(offset+2>b.length)break;const marker=b[offset++];if(marker===0xda||marker===0xd9)break;if(marker===0x01||marker>=0xd0&&marker<=0xd8)continue;const length=v.getUint16(offset);if(length<2||offset+length>b.length)break;if([0xc0,0xc1,0xc2,0xc3,0xc5,0xc6,0xc7,0xc9,0xca,0xcb,0xcd,0xce,0xcf].includes(marker)&&length>=8){height=v.getUint16(offset+3);width=v.getUint16(offset+5);break;}offset+=length;}}
  else if(b.length>=30&&String.fromCharCode(...b.subarray(0,4))==='RIFF'&&String.fromCharCode(...b.subarray(8,12))==='WEBP'){const type=String.fromCharCode(...b.subarray(12,16));if(type==='VP8X'){width=1+b[24]+b[25]*256+b[26]*65536;height=1+b[27]+b[28]*256+b[29]*65536;}else if(type==='VP8 '&&b[23]===0x9d&&b[24]===1&&b[25]===0x2a){width=v.getUint16(26,true)&16383;height=v.getUint16(28,true)&16383;}else if(type==='VP8L'&&b[20]===0x2f){width=1+(b[21]|(b[22]&63)<<8);height=1+((b[22]>>6)|b[23]<<2|(b[24]&15)<<10);}}
  if(!width||!height)throw Error('无法读取图片尺寸，请换一张有效的 JPG、PNG 或 WebP');validateImageSize(width,height);return {width,height};
}
function crc32(bytes){let crc=0xffffffff;for(const byte of bytes){crc^=byte;for(let i=0;i<8;i++)crc=crc>>>1^((crc&1)?0xedb88320:0);}return (crc^0xffffffff)>>>0;}
function chunk(type,data){const result=new Uint8Array(data.length+12),view=new DataView(result.buffer);view.setUint32(0,data.length);result.set(new TextEncoder().encode(type),4);result.set(data,8);view.setUint32(result.length-4,crc32(result.subarray(4,result.length-4)));return result;}
export function pngWithPrintMetadata(input,metadata){const b=new Uint8Array(input),header=imageHeader(b),print=normalizePrintMetadata(metadata,header.width,header.height);if(!print)return b;const additions=[];if(print.dpi){const d=new Uint8Array(9),v=new DataView(d.buffer),x=Math.round(print.dpi/.0254),y=Math.round((print.heightCm?header.height/print.heightCm*2.54:print.dpi)/.0254);v.setUint32(0,x);v.setUint32(4,y);d[8]=1;additions.push(chunk('pHYs',d));}additions.push(chunk('tEXt',new TextEncoder().encode('zhijing-print\0'+JSON.stringify(print))));const parts=[b.subarray(0,8)];let offset=8;while(offset+12<=b.length){const length=new DataView(b.buffer,b.byteOffset+offset,4).getUint32(0),end=offset+length+12;if(end>b.length)throw Error('PNG 数据不完整');const type=String.fromCharCode(...b.subarray(offset+4,offset+8)),text=type==='tEXt'?new TextDecoder().decode(b.subarray(offset+8,end-4)):'';if(type!=='pHYs'&&!text.startsWith('zhijing-print\0'))parts.push(b.subarray(offset,end));if(type==='IHDR')parts.push(...additions);offset=end;}const output=new Uint8Array(parts.reduce((sum,part)=>sum+part.length,0));let cursor=0;for(const part of parts){output.set(part,cursor);cursor+=part.length;}return output;}
